import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { toast } from "react-toastify";
import API from "../services/api";

function EditBlog() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // =========================
  // GET SINGLE BLOG
  // =========================
  useEffect(() => {
    if (!id) {
      toast.error("Invalid blog ID");
      navigate("/dashboard");
      return;
    }

    getBlog();
  }, [id]);

  const getBlog = async () => {
    try {
      setLoading(true);

      const response = await API.get(`/blogs/${id}`);

      console.log("GET BLOG RESPONSE:", response.data);

      /*
        Handles these common backend responses:

        1. { title: "...", content: "..." }

        2. { blog: { title: "...", content: "..." } }

        3. { data: { title: "...", content: "..." } }
      */

      const blog = response.data?.blog || response.data?.data || response.data;

      if (!blog) {
        throw new Error("Blog not found");
      }

      setTitle(blog.title || "");
      setContent(blog.content || "");
    } catch (error) {
      console.error("GET BLOG ERROR:", error);

      toast.error(error.response?.data?.message || "Blog not found");

      setTimeout(() => {
        navigate("/dashboard");
      }, 1500);
    } finally {
      setLoading(false);
    }
  };

  // =========================
  // UPDATE BLOG
  // =========================
  const handleUpdate = async (e) => {
    e.preventDefault();

    // Validation
    if (!title.trim()) {
      toast.warning("Please enter blog title", {
        autoClose: 1500,
      });
      return;
    }

    if (!content.trim()) {
      toast.warning("Please enter blog content", {
        autoClose: 1500,
      });
      return;
    }

    try {
      setSaving(true);

      console.log("UPDATING BLOG ID:", id);

      const response = await API.put(`/blogs/${id}`, {
        title: title.trim(),
        content: content.trim(),
      });

      console.log("UPDATE RESPONSE:", response.data);

      toast.success("Blog updated successfully! ✨", {
        autoClose: 1500,
      });

      // Wait for toast, then go dashboard
      setTimeout(() => {
        navigate("/dashboard");
      }, 1500);
    } catch (error) {
      console.error("UPDATE BLOG ERROR:", error);

      toast.error(error.response?.data?.message || "Failed to update blog", {
        autoClose: 1000,
      });
    } finally {
      setSaving(false);
    }
  };

  // =========================
  // LOADING
  // =========================
  if (loading) {
    return (
      <div className="loader">
        <div className="loader-spinner"></div>
        <p>Loading blog...</p>
      </div>
    );
  }

  // =========================
  // EDIT PAGE
  // =========================
  return (
    <div className="editor-page">
      <div className="editor-card">
        {/* Header */}
        <div className="editor-header">
          <span className="editor-icon">📝</span>

          <h1>Update Your Blog</h1>

          <p>Make changes to your published story.</p>
        </div>

        {/* Form */}
        <form onSubmit={handleUpdate}>
          {/* Title */}
          <div className="form-group">
            <label htmlFor="title">Blog Title</label>

            <input
              id="title"
              type="text"
              placeholder="Enter blog title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              disabled={saving}
            />
          </div>

          {/* Content */}
          <div className="form-group">
            <label htmlFor="content">Content</label>

            <textarea
              id="content"
              rows="12"
              placeholder="Write your blog content..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              disabled={saving}
            />
          </div>

          {/* Buttons */}
          <div className="editor-actions">
            <button
              type="button"
              onClick={() => navigate("/dashboard")}
              className="cancel-btn"
              disabled={saving}
            >
              Cancel
            </button>

            <button type="submit" className="publish-btn" disabled={saving}>
              {saving ? "Saving..." : "Save Changes ✨"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default EditBlog;
